"""Standalone stress test of the worker solver with an independent checker."""
import sys, time, random
sys.path.insert(0, '/workspace/submission')
import numpy as np
from te.engine.worker import solve_worker


def tol(a, b):
    return 1e-7 + 1e-7 * max(abs(a), abs(b))


def check(owned, paths, caps, demand, mode, rho, B, prop):
    errs = []
    E = len(caps)
    if prop["status"] != "optimal":
        return errs
    flow = prop["flow"]
    if len(flow) != len(owned):
        return ["flow rows"]
    x = {}
    for i, k in enumerate(owned):
        if len(flow[i]) != len(paths[k]):
            return ["flow row len"]
        for p, v in enumerate(flow[i]):
            path = paths[k][p]
            avail = path is not None and all(caps[e] > 0 for e in path)
            if (not avail) or demand[k] <= 0:
                if v != 0:
                    errs.append("forced zero (%d,%d)=%r" % (k, p, v))
            if not -1e-12 <= v <= 1e9:
                errs.append("flow range %r" % v)
            x[(k, p)] = float(v)
    L = [0.0] * E
    for k in owned:
        for p, path in enumerate(paths[k]):
            v = x[(k, p)]
            if v:
                for e in path:
                    L[e] += v
    for e in range(E):
        if caps[e] <= 0 and prop["edge_load"][e] != 0:
            errs.append("withdrawn load %d" % e)
        if abs(prop["edge_load"][e] - L[e]) > tol(prop["edge_load"][e], L[e]):
            errs.append("load %d %r %r" % (e, prop["edge_load"][e], L[e]))
    for k in owned:
        s = sum(x[(k, p)] for p in range(len(paths[k])))
        if mode == "route":
            if abs(s - demand[k]) > tol(s, demand[k]):
                errs.append("route sum %d %r %r" % (k, s, demand[k]))
        else:
            if s > demand[k] + tol(s, demand[k]):
                errs.append("admit sum %d" % k)
    pot = prop["potential"]
    if len(pot) != len(owned):
        return ["potential len"]
    for i, k in enumerate(owned):
        if demand[k] <= 0 and pot[i] != 0:
            errs.append("zero demand potential %d" % k)
        if not -1e9 <= pot[i] <= 1e9:
            errs.append("potential range")
        if mode == "admit" and pot[i] < -tol(pot[i], 0.0):
            errs.append("admit potential %r" % pot[i])
    G = {}
    for k in owned:
        if demand[k] <= 0:
            continue
        for p, path in enumerate(paths[k]):
            if path is None or not all(caps[e] > 0 for e in path):
                continue
            g = x[(k, p)]
            for e in path:
                g += rho * (L[e] / caps[e] - B[e]) / caps[e]
            if mode == "admit":
                g -= 1.0
            G[(k, p)] = g
    for i, k in enumerate(owned):
        for (kk, p), g in G.items():
            if kk != k:
                continue
            val = g + pot[i]
            if val < -tol(val, 0.0):
                errs.append("G+lam<0 (%d,%d) %r" % (k, p, val))
    f = 0.5 * sum(v * v for v in x.values())
    for e in range(E):
        if caps[e] > 0:
            f += 0.5 * rho * (L[e] / caps[e] - B[e]) ** 2
    if mode == "admit":
        f -= sum(x.values())
    D = f
    for (k, p), g in G.items():
        D -= x[(k, p)] * g
    for i, k in enumerate(owned):
        D -= demand[k] * pot[i]
    if abs(f - D) > tol(f, D):
        errs.append("f!=D %r %r diff %r tol %r" % (f, D, f - D, tol(f, D)))
    return errs


def gen_problem(rng):
    nodes = rng.randint(2, 8)
    pairs = [(u, v) for u in range(nodes) for v in range(nodes) if u != v]
    rng.shuffle(pairs)
    nE = rng.randint(1, 20)
    edges = pairs[:nE]
    caps = [float(rng.choice([0, 0, 1, 1, 2, 5, 1000])) for _ in edges]
    adj = {n: [] for n in range(nodes)}
    for eid, (u, v) in enumerate(edges):
        adj[u].append((eid, v))
    ncom = rng.randint(0, 10)
    coms = []
    for _ in range(ncom):
        s = rng.randrange(nodes)
        t = rng.randrange(nodes)
        while t == s:
            t = rng.randrange(nodes)
        slots = []
        used = set()
        for _ in range(rng.randint(0, 6)):
            if rng.random() < 0.15:
                slots.append(None)
                continue
            path = []
            cur = s
            seen = {s}
            for _ in range(rng.randint(1, 8)):
                opts = [e for e, v in adj[cur] if v not in seen]
                if not opts:
                    break
                e = rng.choice(opts)
                path.append(e)
                cur = edges[e][1]
                seen.add(cur)
                if cur == t:
                    break
            if cur == t and tuple(path) not in used:
                used.add(tuple(path))
                slots.append(path)
            else:
                slots.append(None)
        coms.append({"source": s, "sink": t,
                     "demand": float(rng.choice([0, 0, 1, 2, 1000])),
                     "paths": slots})
    owned = sorted(rng.sample(range(ncom), rng.randint(0, ncom))) if ncom else []
    mode = rng.choice(["route", "admit"])
    rho = rng.randint(1, 8)
    scale = 10.0 ** rng.randint(-2, 4)
    B = [rng.gauss(0, 1) * scale for _ in edges]
    paths = [c["paths"] for c in coms]
    demand = [c["demand"] for c in coms]
    return owned, paths, caps, demand, mode, rho, B


def main(seed0, N):
    rng = random.Random(seed0)
    bad = 0
    t0 = time.time()
    worst = 0.0
    for i in range(N):
        owned, paths, caps, demand, mode, rho, B = gen_problem(rng)
        t = time.time()
        prop = solve_worker(owned, paths, caps, demand, mode, rho, B)
        worst = max(worst, time.time() - t)
        if prop["status"] == "optimal":
            errs = check(owned, paths, caps, demand, mode, rho, B, prop)
        else:
            errs = []
            unr = [k for k in owned if demand[k] > 0
                   and not any(p is not None and all(caps[e] > 0 for e in p)
                               for p in paths[k])]
            if mode != "route" or prop["unroutable"] != unr:
                errs = ["bad infeasible %r %r" % (prop.get("unroutable"), unr)]
        if errs:
            bad += 1
            if bad < 6:
                print("seed", seed0 + i, errs[:4])
                print("   owned", owned, "mode", mode, "rho", rho, "caps", caps,
                      "demand", demand, "B", [round(b, 3) for b in B])
                print("   paths", paths)
    print("done", N, "bad", bad, "time %.1fs worst %.3fs" % (time.time() - t0, worst))


if __name__ == "__main__":
    main(int(sys.argv[1]), int(sys.argv[2]))
